{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A quiet map for steadier living</title>
  <meta name="description" content="Personal sessions, short frameworks, and small habit designs to steady your energy and shape reliable days.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <div class="site-wrap">
    <header class="site-header">
      <div class="brand">
        <div class="logo-mark" aria-hidden="true"></div>
        <div class="brand-text">
          <strong>{{BUSINESS_NAME}}</strong>
          <span class="tag">Minimal guidance. Measured change.</span>
        </div>
      </div>
      <nav class="main-nav">
        <a href="about.html">Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Journeys</a>
        <a href="pricing.html">Rates</a>
        <a href="testimonials.html">Praise</a>
        <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html" class="muted">Connect</a>
      </nav>
    </header>

    <main>
      <!-- Hero -->
      <section class="hero">
        <div class="hero-inner">
          <h1>Small designs that hold steady through the day.</h1>
          <p class="lead">I help busy people shape dependable habits, clear decision rules, and short sessions that shift momentum without noise.</p>
          <div class="hero-actions">
            <a class="button primary" href="book.html">Start a short session</a>
            <a class="button ghost" href="#planner">Try the Session Planner</a>
          </div>
        </div>
        <svg class="hero-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"/></svg>
      </section>

      <!-- Social proof -->
      <section class="social-proof">
        <p class="muted">Trusted by professionals, creatives, and caretakers across {{CITY}}, {{STATE}}.</p>
        <div class="logos" aria-hidden="true">
          <span class="pill">Team Lead</span>
          <span class="pill">Design Studio</span>
          <span class="pill">Wellness Collective</span>
        </div>
      </section>

      <!-- Benefits -->
      <section class="benefits">
        <h2>What I help you build</h2>
        <ul class="benefit-list">
          <li>
            <strong>Actionable rhythms</strong>
            <p>Simple sequences you can replicate in busy windows of time.</p>
          </li>
          <li>
            <strong>Habit scaffolds</strong>
            <p>Seven-day starters and checklists so good intentions become practice.</p>
          </li>
          <li>
            <strong>Session templates</strong>
            <p>Brief, guided sessions you can run on your own or with my support.</p>
          </li>
        </ul>
      </section>

      <!-- Process -->
      <section class="process">
        <h2>How we move forward</h2>
        <ol>
          <li><strong>Listen</strong> — a short intake to learn what matters to you now.</li>
          <li><strong>Design</strong> — craft a tailored set of micro-practices and an initial schedule.</li>
          <li><strong>Try</strong> — a focused 2-week play to notice what fits.</li>
          <li><strong>Refine</strong> — adjust habits and session cadence for real life.</li>
        </ol>
      </section>

      <!-- Session Planner Widget -->
      <section id="planner" class="widget session-planner">
        <h2>Session Planner</h2>
        <p class="muted">Build a single-session plan you can use immediately. Export the summary or copy it to your clipboard.</p>
        <form id="planner-form">
          <label>Session focus</label>
          <select id="planner-focus">
            <option value="energy">Reset energy</option>
            <option value="clarity">Gain clarity</option>
            <option value="sleep">Evening wind-down</option>
            <option value="movement">Gentle movement</option>
          </select>

          <label>Length</label>
          <select id="planner-length">
            <option value="10">10 minutes</option>
            <option value="20">20 minutes</option>
            <option value="30">30 minutes</option>
          </select>

          <label>Tone</label>
          <select id="planner-tone">
            <option value="guided">Guided prompts</option>
            <option value="solo">Solo practice</option>
            <option value="mixed">Mix of prompts and silence</option>
          </select>

          <button type="button" id="planner-build" class="button">Build plan</button>
        </form>

        <pre id="planner-output" aria-live="polite" class="plan-output">Your session summary will appear here.</pre>
        <div class="widget-actions">
          <button id="planner-copy" class="button ghost">Copy summary</button>
          <a id="planner-save" class="button" download="session-plan.txt">Download</a>
        </div>
      </section>

      <!-- Habit Builder -->
      <section class="widget habit-builder">
        <h2>7‑Day Challenge Generator</h2>
        <p class="muted">Choose a theme and generate a printable checklist to carry into the week.</p>
        <div class="habit-controls">
          <label>Theme</label>
          <select id="habit-theme">
            <option value="movement">Gentle movement</option>
            <option value="mind">Mini-reflection</option>
            <option value="sleep">Evening routine</option>
            <option value="focus">Work block setup</option>
          </select>
          <label>Intensity</label>
          <select id="habit-intensity">
            <option value="low">Low</option>
            <option value="moderate">Moderate</option>
            <option value="stretch">Stretch</option>
          </select>
          <button id="habit-generate" class="button">Create checklist</button>
        </div>
        <div id="habit-checklist" class="checklist" aria-live="polite">Generate a 7-day checklist to preview here.</div>
        <div class="widget-actions">
          <button id="habit-copy" class="button ghost">Copy checklist</button>
          <button id="habit-print" class="button">Print checklist</button>
        </div>
      </section>

      <!-- FAQ -->
      <section class="faq">
        <h2>Questions people ask</h2>
        <details>
          <summary>How long are sessions?</summary>
          <p>Sessions are framed at 20 or 50 minutes; short check-ins and guided practices are also available.</p>
        </details>
        <details>
          <summary>Are there templates I can use on my own?</summary>
          <p>Yes. You get short session templates and checklists you can reuse independently.</p>
        </details>
        <details>
          <summary>Do you provide medical advice?</summary>
          <p>No. The work focuses on habits, practices, and practical routines — not clinical care.</p>
        </details>
      </section>

      <!-- CTA -->
      <section class="final-cta">
        <h2>Ready to try a focused shift?</h2>
        <p class="muted">Book a first short session to start a practical, gentle change. Small designs, steady returns.</p>
        <div class="cta-actions">
          <a class="button primary" href="book.html">Reserve a brief session</a>
          <a class="button ghost" href="contact.html">Ask a question</a>
        </div>
      </section>
    </main>

    <footer class="site-footer">
      <div class="foot-inner">
        <div>© <span id="year"></span> {{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <nav class="foot-nav">
          <a href="sitemap.xml">Sitemap</a>
          <a href="privacy.html">Privacy</a>
        </nav>
      </div>
    </footer>
  </div>
  <script src="assets/js/main.js"></script>
</body>
</html>"} 
